<?php require 'includes/init.php';$u=require_login();$profile=logged_in_user_record();$err='';$b=Booking::byRef($_GET['ref']??'',$u['id']);if(!$b||$b['status']!=='pending')exit('This booking can no longer be paid. <a href="index.php">Start again</a>.');if($_SERVER['REQUEST_METHOD']==='POST'){try{if(($_POST['demo_result']??'success')==='fail'){$err=Payment::recordFailed($b,'card','Simulated card payment was declined. Please try again.');}else{$num=preg_replace('/\D/','',$_POST['number']??'');$cvv=$_POST['cvv']??'';if(strlen($num)<13||strlen($num)>19||!preg_match('/^\d{3,4}$/',$cvv)||!preg_match('/^\d{2}\/\d{2}$/',$_POST['expiry']??'')||trim($_POST['holder']??'')==='')$err='Check your card details and try again.';else{Payment::payByCard($b,substr($num,-4));header('Location: confirmation.php?ref='.$b['booking_ref']);exit;}}}catch(Throwable $e){$err=$e->getMessage();}}include 'includes/header.php'; ?>
<main class="page"><div class="wrap"><div class="auth" style="max-width:620px"><form class="card panel" method="post" autocomplete="off"><h2>Card Payment</h2><?php if($err): ?><div class="err"><?= e($err) ?></div><?php endif; ?><div class="credit-card"><b style="font-size:25px;text-align:right">VISA</b><div class="num">**** **** **** 4242</div><div style="display:flex;justify-content:space-between"><span><?= e($profile['full_name']) ?></span><span>MM/YY</span></div></div><div class="field"><label>Name on Card</label><input name="holder" required></div><div class="field"><label>Card Number</label><input name="number" inputmode="numeric" placeholder="1234 5678 9012 3456" required></div><div class="grid2"><div class="field"><label>Expiry Date</label><input name="expiry" placeholder="MM/YY" required></div><div class="field"><label>CVV</label><input name="cvv" inputmode="numeric" placeholder="123" required></div></div><button class="btn primary full" type="submit" name="demo_result" value="success">🔒 Simulate Successful Payment <?= naira($b['total_amount']) ?></button><button class="btn outline full" style="margin-top:10px" type="submit" name="demo_result" value="fail" formnovalidate>Simulate Failed Card Payment</button><p class="helper">Demo payment: full card number and CVV are not stored.</p></form></div></div></main><?php include 'includes/footer.php'; ?>
